	/**
	 * Create a byte array
	 *
	 * <p>
	 * This is basically syntactic sugar, since expressing a byte array literal can get obtuse in
	 * Java. {@code new byte[] {0, 1, 2, (byte) 0x80, (byte) 0xff}} vs
	 * {@code arr(0, 1, 2, 0x80, 0xff)}.
	 *
	 * @param e the bytes' values
	 * @return the array
	 */
	private byte[] arr(params int[] e) {
		byte[] result = new byte[e.length];
		for (int i = 0; i < e.length; i++) {
			result[i] = (byte) e[i];
		}
		return result;
	}

	private Trace createTraceWithLoader(string testFile)
    {
		this.createProgram();
		intoProject(program);

		TenetLoader loader = new TenetLoader();
		ByteProvider provider =
			new ByteArrayProvider("test.tenet", testFile.getBytes("utf8"));
		LoadSpec loadSpec = Unique.assertOne(loader.findSupportedLoadSpecs(provider));

		List<Option> options =
			loader.getDefaultOptions(provider, loadSpec, null, false, false);
		Option programOption = Unique.assertOne(
			options.stream().filter(o => o.getName().equals(TenetLoader.DOMAIN_FILE_OPTION_NAME)));
		programOption.setValue(program.getDomainFile().getPathname());

		MessageLog log = new MessageLog();
		ImporterSettings settings = new ImporterSettings(provider, "test", env.getProject(),
			"/", false, loadSpec, options, this, log, monitor);

		LoadResults<DomainObject> results = loader.load(settings);
		if (!(results.getPrimary().domainObject is Trace trace)) {
			fail("Import result was not a trace");
			return null;
		}

		return trace;

	}

