	/*
	 * Test that the loader parses register values properly
	 */
	/* @Test */
	public void testRegisterValues()
    {
		string testFile = """
				slide=0x0
				pc=0x1,r0=0x1234
				pc=0x2,r1=0x4321
				pc=0x3,r1=0x4321
				pc=0x4,r1=0x4321
				pc=0x5,r1=0x4321
				pc=0x6,r1=0x4321
				pc=0x7,r1=0x4321
				pc=0x8,r1=0x4321
				pc=0x9,r1=0x4321
				pc=0xa,r1=0x4321
				""";

		Trace trace = createTraceWithLoader(testFile);

		TraceThread thread = Unique.assertOne(trace.getThreadManager().getAllThreads());
		TraceMemorySpace regs =
			trace.getMemoryManager().getMemoryRegisterSpace(thread, false);

		assertNotNull(regs);
		assertEquals("1",
			regs.getValue(0, program.getLanguage().getProgramCounter())
					.getUnsignedValue()
					.toString(16));

		assertEquals("2",
			regs.getValue(1, program.getLanguage().getProgramCounter())
					.getUnsignedValue()
					.toString(16));

	}

